"use client"

import { useState } from "react"
import { Phone, Ambulance, FireExtinguisher, Shield, ChevronLeft } from "lucide-react"
import Link from "next/link"

export default function EmergencyPage() {
  const [calling, setCalling] = useState(false)

  const emergencyContacts = [
    { icon: Phone, label: "Emergency Hotline", number: "911", color: "bg-red-500" },
    { icon: Ambulance, label: "Ambulance", number: "(043) 288-8888", color: "bg-blue-500" },
    { icon: FireExtinguisher, label: "Fire Department", number: "(043) 288-7777", color: "bg-orange-600" },
    { icon: Shield, label: "Police Station", number: "(043) 288-6666", color: "bg-indigo-600" },
  ]

  const handleEmergencyCall = async (number: string, label: string) => {
    setCalling(true)
    // This would integrate with Laravel backend
    // await fetch('/api/emergency/call', {
    //   method: 'POST',
    //   body: JSON.stringify({ number, label, timestamp: new Date() })
    // })

    // Simulate call
    setTimeout(() => {
      window.location.href = `tel:${number}`
      setCalling(false)
    }, 500)
  }

  return (
    <div className="flex flex-col min-h-screen bg-gradient-to-b from-red-50 to-white">
      {/* Header */}
      <header className="bg-red-600 text-white px-4 py-4">
        <div className="flex items-center gap-3 mb-4">
          <Link href="/">
            <ChevronLeft className="w-6 h-6" />
          </Link>
          <h1 className="text-xl font-bold">Emergency Services</h1>
        </div>
        <p className="text-red-100 text-sm">Quick access to emergency contacts and services</p>
      </header>

      {/* Main Content */}
      <main className="flex-1 px-4 py-6">
        {/* Emergency Alert */}
        <div className="bg-red-100 border-l-4 border-red-600 p-4 rounded-lg mb-6">
          <p className="text-red-900 font-semibold text-sm">For life-threatening emergencies, call 911 immediately</p>
        </div>

        {/* One-Tap Emergency Call */}
        <div className="mb-8">
          <h2 className="text-lg font-bold text-gray-900 mb-4">One-Tap Emergency Call</h2>
          <button
            onClick={() => handleEmergencyCall("911", "Emergency Hotline")}
            disabled={calling}
            className="w-full bg-red-600 text-white p-6 rounded-2xl shadow-lg active:scale-95 transition-transform disabled:opacity-50"
          >
            <div className="flex flex-col items-center gap-3">
              <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center">
                <Phone className="w-10 h-10 text-red-600" />
              </div>
              <div>
                <p className="text-2xl font-bold">Call 911</p>
                <p className="text-red-100 text-sm">Emergency Hotline</p>
              </div>
            </div>
          </button>
        </div>

        {/* Emergency Contacts */}
        <div className="mb-8">
          <h2 className="text-lg font-bold text-gray-900 mb-4">Emergency Contacts</h2>
          <div className="space-y-3">
            {emergencyContacts.map((contact, index) => (
              <button
                key={index}
                onClick={() => handleEmergencyCall(contact.number, contact.label)}
                className="w-full flex items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-100 active:scale-98 transition-transform"
              >
                <div className={`${contact.color} w-14 h-14 rounded-full flex items-center justify-center`}>
                  <contact.icon className="w-7 h-7 text-white" />
                </div>
                <div className="flex-1 text-left">
                  <h3 className="font-semibold text-gray-900">{contact.label}</h3>
                  <p className="text-sm text-gray-600">{contact.number}</p>
                </div>
                <Phone className="w-5 h-5 text-gray-400" />
              </button>
            ))}
          </div>
        </div>

        {/* Request Ambulance */}
        <div>
          <h2 className="text-lg font-bold text-gray-900 mb-4">Request Assistance</h2>
          <Link
            href="/emergency/ambulance"
            className="w-full flex items-center gap-4 bg-gradient-to-r from-blue-500 to-blue-600 text-white p-5 rounded-xl shadow-md"
          >
            <div className="w-14 h-14 bg-white/20 rounded-full flex items-center justify-center">
              <Ambulance className="w-7 h-7 text-white" />
            </div>
            <div className="flex-1 text-left">
              <h3 className="font-bold text-lg">Request Ambulance</h3>
              <p className="text-blue-100 text-sm">Share your location for quick response</p>
            </div>
          </Link>
        </div>

        {/* Safety Tips */}
        <div className="mt-8 bg-orange-50 p-5 rounded-xl border border-orange-100">
          <h3 className="font-bold text-gray-900 mb-3">Safety Tips</h3>
          <ul className="space-y-2 text-sm text-gray-700">
            <li className="flex gap-2">
              <span className="text-orange-600">•</span>
              <span>Stay calm and speak clearly when calling emergency services</span>
            </li>
            <li className="flex gap-2">
              <span className="text-orange-600">•</span>
              <span>Provide your exact location and describe the emergency</span>
            </li>
            <li className="flex gap-2">
              <span className="text-orange-600">•</span>
              <span>Follow the dispatcher's instructions carefully</span>
            </li>
          </ul>
        </div>
      </main>
    </div>
  )
}
